content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --radius: 12px;
  --shadow-color: rgba(0, 0, 0, 0.1);
  --shadow-color-sub: rgba(0, 0, 0, 0.06);
  --shadow: 0 4px 6px -1px var(--shadow-color), 0 2px 4px -1px var(--shadow-color-sub);
}

@media (prefers-color-scheme: dark) {
  :root {
    --primary-color: #6366f1;
    --primary-hover: #818cf8;
    --bg-color: #0f172a;
    --card-bg: #1e293b;
    --text-main: #f8fafc;
    --text-muted: #94a3b8;
    --border-color: #334155;
    --shadow-color: rgba(0, 0, 0, 0.4);
    --shadow-color-sub: rgba(0, 0, 0, 0.2);
  }
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
}

.app-container {
  max-width: 1000px;
  margin: 0 auto;
  padding: 20px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.header {
  margin-bottom: 24px;
  text-align: center;
}

.title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-main);
}

.total-amount {
  font-size: 1.1rem;
  color: var(--text-muted);
  margin-top: 4px;
}

.main-content {
  display: flex;
  flex-direction: column;
  gap: 20px;
  flex: 1;
}

.dashboard {
  display: grid;
  grid-template-columns: 1fr;
  gap: 20px;
}

@media (min-width: 768px) {
  .dashboard {
    grid-template-columns: 1fr 1fr;
  }
}

.card {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 20px;
  display: flex;
  flex-direction: column;
}

.chart-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 300px;
}

.list-container {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.expense-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.2s ease;
  background-color: var(--card-bg);
}

.expense-item:hover {
  background-color: var(--border-color);
  border-color: var(--primary-color);
}

.expense-item.active {
  border-color: var(--primary-color);
  background-color: var(--border-color);
}

.selected-detail {
  margin-top: 16px;
  padding: 16px;
  background-color: var(--bg-color);
  border-radius: 8px;
  border-left: 4px solid var(--primary-color);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 8px 16px;
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: 6px;
  border: none;
  cursor: pointer;
  background-color: var(--primary-color);
  color: white;
  transition: background-color 0.2s;
}

.btn:hover {
  background-color: var(--primary-hover);
}

@media (max-width: 480px) {
  .app-container {
    padding: 12px;
  }
  .title {
    font-size: 1.5rem;
  }
  .total-amount {
    font-size: 1rem;
  }
  .card {
    padding: 14px;
  }
  .expense-item {
    padding: 10px 12px;
  }
}

export type ExpenseCategory = 
  | '食費'
  | '家賃'
  | '光熱費・水道'
  | '通信費'
  | '娯楽・交際費'
  | '日用品';

export interface ExpenseItem {
  id: string;
  category: ExpenseCategory;
  amount: number;
  color: string;
  date?: string;
  memo?: string;
}

import { ResponsiveContainer, PieChart, Pie, Cell, Tooltip, Legend } from 'recharts';
import { ExpenseItem } from './types';
import './index.css';

interface ExpenseChartProps {
  items?: ExpenseItem[];
  selectedId?: string | null;
  onSelect?: (id: string) => void;
}

export default function ExpenseChart({ items = [], selectedId = null, onSelect }: ExpenseChartProps) {
  const total = items.reduce((sum, item) => sum + item.amount, 0);

  return (
    <div className="card chart-container">
      <h3 style={{ marginBottom: '16px', fontSize: '1.2rem', fontWeight: 600 }}>支出内訳グラフ</h3>
      {items.length === 0 ? (
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', height: '200px', color: 'var(--text-muted)' }}>
          <svg style={{ width: '48px', height: '48px', marginBottom: '8px', stroke: 'currentColor' }} fill="none" viewBox="0 0 24 24" strokeWidth="1.5">
            <path strokeLinecap="round" strokeLinejoin="round" d="M10.5 6a7.5 7.5 0 107.5 7.5h-7.5V6z" />
            <path strokeLinecap="round" strokeLinejoin="round" d="M13.5 10.5H21A7.5 7.5 0 0013.5 3v7.5z" />
          </svg>
          <p>データがありません</p>
        </div>
      ) : (
        <div style={{ width: '100%', height: '260px' }}>
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie
                data={items}
                dataKey="amount"
                nameKey="category"
                cx="50%"
                cy="50%"
                outerRadius={75}
                innerRadius={35}
                paddingAngle={4}
                onClick={(entry: any) => entry && entry.id && onSelect?.(entry.id)}
                style={{ cursor: 'pointer' }}
              >
                {items.map((entry) => (
                  <Cell
                    key={`cell-${entry.id}`}
                    fill={entry.color}
                    stroke={selectedId === entry.id ? 'var(--text-main)' : 'none'}
                    strokeWidth={selectedId === entry.id ? 2 : 0}
                  />
                ))}
              </Pie>
              <Tooltip
                formatter={(value: any) => {
                  const numValue = Number(value);
                  const percentage = total > 0 ? ((numValue / total) * 100).toFixed(1) : '0';
                  return [`¥${numValue.toLocaleString()} (${percentage}%)`, '金額'];
                }}
                contentStyle={{ backgroundColor: 'var(--card-bg)', color: 'var(--text-main)', borderRadius: '8px', border: '1px solid var(--border-color)' }}
              />
              <Legend formatter={(value) => <span style={{ color: 'var(--text-main)', fontSize: '0.8rem' }}>{value}</span>} />
            </PieChart>
          </ResponsiveContainer>
        </div>
      )}
      <div style={{ marginTop: '8px', fontSize: '0.9rem', color: 'var(--text-muted)' }}>
        総額: ¥{total.toLocaleString()} (項目をクリックすると詳細を表示します)
      </div>
    </div>
  );
}

import { useState, useMemo } from 'react';
import { ExpenseItem } from './types';
import './index.css';

interface ExpenseListProps {
  items?: ExpenseItem[];
  selectedId?: string | null;
  onSelect?: (id: string) => void;
}

export default function ExpenseList({ items = [], selectedId = null, onSelect }: ExpenseListProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [sortBy, setSortBy] = useState<'amount-desc' | 'amount-asc' | 'category'>('amount-desc');

  const total = items.reduce((sum, item) => sum + item.amount, 0);

  const filteredAndSortedItems = useMemo(() => {
    return items
      .filter((item) => item.category.toLowerCase().includes(searchTerm.toLowerCase()))
      .sort((a, b) => {
        if (sortBy === 'amount-desc') return b.amount - a.amount;
        if (sortBy === 'amount-asc') return a.amount - b.amount;
        if (sortBy === 'category') return a.category.localeCompare(b.category, 'ja');
        return 0;
      });
  }, [items, searchTerm, sortBy]);

  const selectedItem = items.find((item) => item.id === selectedId);

  return (
    <div className="card">
      <h3 style={{ marginBottom: '16px', fontSize: '1.2rem', fontWeight: 600 }}>支出項目一覧</h3>

      <div style={{ display: 'flex', gap: '10px', marginBottom: '16px', flexWrap: 'wrap' }}>
        <input
          type="text"
          placeholder="カテゴリを検索..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{
            flex: '1 1 150px',
            padding: '8px 12px',
            borderRadius: '6px',
            border: '1px solid var(--border-color)',
            fontSize: '0.875rem',
            backgroundColor: 'var(--card-bg)',
            color: 'var(--text-main)',
            outline: 'none',
          }}
        />
        <select
          value={sortBy}
          onChange={(e) => setSortBy(e.target.value as any)}
          style={{
            padding: '8px 12px',
            borderRadius: '6px',
            border: '1px solid var(--border-color)',
            fontSize: '0.875rem',
            backgroundColor: 'var(--card-bg)',
            color: 'var(--text-main)',
            cursor: 'pointer',
            outline: 'none',
          }}
        >
          <option value="amount-desc">金額が高い順</option>
          <option value="amount-asc">金額が低い順</option>
          <option value="category">カテゴリ名順</option>
        </select>
      </div>

      <div className="list-container">
        {filteredAndSortedItems.length === 0 ? (
          <p style={{ textAlign: 'center', color: 'var(--text-muted)', padding: '16px' }}>該当する項目がありません</p>
        ) : (
          filteredAndSortedItems.map((item) => {
            const isSelected = item.id === selectedId;
            const percentage = total > 0 ? ((item.amount / total) * 100).toFixed(1) : '0';
            return (
              <div
                key={item.id}
                className={`expense-item ${isSelected ? 'active' : ''}`}
                onClick={() => onSelect?.(item.id)}
              >
                <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                  <span
                    style={{
                      width: '12px',
                      height: '12px',
                      borderRadius: '50%',
                      backgroundColor: item.color,
                      display: 'inline-block',
                    }}
                  />
                  <span style={{ fontWeight: 500 }}>{item.category}</span>
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                  <span style={{ color: 'var(--text-muted)', fontSize: '0.85rem' }}>{percentage}%</span>
                  <span style={{ fontWeight: 600 }}>¥{item.amount.toLocaleString()}</span>
                </div>
              </div>
            );
          })
        )}
      </div>

      {selectedItem && (
        <div className="selected-detail" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '12px' }}>
          <div>
            <h4 style={{ fontSize: '1rem', fontWeight: 600, marginBottom: '4px', color: 'var(--primary-color)' }}>
              選択中の項目詳細: {selectedItem.category}
            </h4>
            <p style={{ fontSize: '0.95rem' }}>
              金額: <strong>¥{selectedItem.amount.toLocaleString()}</strong> （全体の{' '}
              {total > 0 ? ((selectedItem.amount / total) * 100).toFixed(1) : 0}%）
            </p>
          </div>
          <button
            className="btn"
            onClick={() => onSelect?.('')}
            style={{ fontSize: '0.85rem', padding: '8px 16px', backgroundColor: 'var(--primary-hover)' }}
          >
            選択を解除
          </button>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, FormEvent } from 'react';
import { ExpenseItem, ExpenseCategory } from './types';
import ExpenseChart from './ExpenseChart';
import ExpenseList from './ExpenseList';
import { initialExpenses } from './constants';
import './index.css';

const CATEGORY_COLORS: Record<ExpenseCategory, string> = {
  '食費': '#4f46e5',
  '家賃': '#06b6d4',
  '光熱費・水道': '#10b981',
  '通信費': '#f59e0b',
  '娯楽・交際費': '#ec4899',
  '日用品': '#8b5cf6',
};

export default function App() {
  const [items, setItems] = useState<ExpenseItem[]>(() => {
    const saved = localStorage.getItem('expenses');
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {
        console.error('Failed to load expenses from localStorage', e);
      }
    }
    return initialExpenses;
  });

  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [category, setCategory] = useState<ExpenseCategory>('食費');
  const [amount, setAmount] = useState<string>('');

  useEffect(() => {
    localStorage.setItem('expenses', JSON.stringify(items));
  }, [items]);

  useEffect(() => {
    if (selectedId && !items.some((item) => item.id === selectedId)) {
      setSelectedId(null);
    }
  }, [items, selectedId]);

  const totalAmount = items.reduce((sum, item) => sum + item.amount, 0);

  const handleSelect = (id: string) => {
    if (id === '' || selectedId === id) {
      setSelectedId(null);
    } else {
      setSelectedId(id);
    }
  };

  const handleAdd = (e: FormEvent) => {
    e.preventDefault();
    const numericAmount = Number(amount);
    if (isNaN(numericAmount) || numericAmount <= 0) return;

    const newItem: ExpenseItem = {
      id: Date.now().toString(),
      category,
      amount: numericAmount,
      color: CATEGORY_COLORS[category] || '#4f46e5',
    };

    setItems((prev) => [newItem, ...prev]);
    setAmount('');
  };

  const handleDelete = () => {
    if (!selectedId) return;
    setItems((prev) => prev.filter((item) => item.id !== selectedId));
    setSelectedId(null);
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">家計簿ダッシュボード</h1>
        <div className="total-amount">今月の総支出: ¥{totalAmount.toLocaleString()}</div>
      </header>

      <main className="main-content">
        <div className="card" style={{ marginBottom: '20px' }}>
          <h3 style={{ marginBottom: '12px', fontSize: '1.1rem', fontWeight: 600 }}>新規支出の追加</h3>
          <form onSubmit={handleAdd} style={{ display: 'flex', gap: '10px', flexWrap: 'wrap', alignItems: 'center' }}>
            <select
              value={category}
              onChange={(e) => setCategory(e.target.value as ExpenseCategory)}
              style={{
                padding: '8px 12px',
                borderRadius: '6px',
                border: '1px solid var(--border-color)',
                fontSize: '0.875rem',
                backgroundColor: 'var(--card-bg)',
                color: 'var(--text-main)',
                outline: 'none',
              }}
            >
              {(['食費', '家賃', '光熱費・水道', '通信費', '娯楽・交際費', '日用品'] as ExpenseCategory[]).map((cat) => (
                <option key={cat} value={cat}>
                  {cat}
                </option>
              ))}
            </select>
            <input
              type="number"
              placeholder="金額（例: 5000）"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              required
              style={{
                padding: '8px 12px',
                borderRadius: '6px',
                border: '1px solid var(--border-color)',
                fontSize: '0.875rem',
                backgroundColor: 'var(--card-bg)',
                color: 'var(--text-main)',
                outline: 'none',
                width: '160px',
              }}
            />
            <button type="submit" className="btn">追加</button>
            {selectedId && (
              <button
                type="button"
                className="btn"
                onClick={handleDelete}
                style={{ backgroundColor: '#ef4444' }}
              >
                選択項目を削除
              </button>
            )}
          </form>
        </div>

        <div className="dashboard">
          <ExpenseChart items={items} selectedId={selectedId} onSelect={handleSelect} />
          <ExpenseList items={items} selectedId={selectedId} onSelect={handleSelect} />
        </div>
      </main>
    </div>
  );
}

